pub fn remove(q: &Queue, k: Kind) -> Queue {
    let p = pos(q, k);
    let c = pending_count(q);
    let last = if c == 0 { 0 } else { c - 1 };
    let n0 = with_slot(q, k, None);
    let n1 = fill_hole(&n0, Kind::PollStatus, last, p);
    let n2 = fill_hole(&n1, Kind::PollCurrentCook, last, p);
    let n3 = fill_hole(&n2, Kind::PollRecipes, last, p);
    let n4 = fill_hole(&n3, Kind::UserStart, last, p);
    let n5 = fill_hole(&n4, Kind::UserStop, last, p);
    fill_hole(&n5, Kind::UserNextStage, last, p)
}

transition.kernel_code:
pub fn transition(s: &Queue, cmd: &Command) -> Result<(Option<Queue>, Reply), Error> {
    match cmd {
        Command::Enqueue { kind, time, replace } => {
            let n = enqueue(s, *kind, *time, *replace);
            Ok((Some(n), Reply::Queued))
        }
        Command::PopDue { now } => {
            let (n, popped) = pop_due(s, *now);
            Ok((Some(n), Reply::Popped(popped)))
        }
        Command::PollOk => {
            let mut n = *s;
            n.fail_count = 0;
            Ok((Some(n), Reply::Queued))
        }
        Command::PollFail => {
            let mut n = *s;
            n.fail_count = incr_sat(s.fail_count);
            Ok((Some(n), Reply::Queued))
        }
        Command::Peek => Ok((
            None,
            Reply::Health {
                fail_count: s.fail_count,
                interval: next_poll_interval(s.fail_count),
                offline: is_offline(s.fail_count),
            },
        )),
    }
}

