pub fn consider(best: Option<(u64, Kind, u8)>, s: Option<u64>, k: Kind, p: u8, now: u64) -> Option<(u64, Kind, u8)> {
    match s {
        None => best,
        Some(t) => {
            if t > now {
                best
            } else {
                match best {
                    None => Some((t, k, p)),
                    Some(b) => {
                        if better(t, k, p, b.0, b.1, b.2) {
                            Some((t, k, p))
                        } else {
                            best
                        }
                    }
                }
            }
        }
    }
}

