pub fn fill_hole(q: &Queue, j: Kind, last: u8, p: u8) -> Queue {
    match slot(q, j) {
        None => *q,
        Some(_) => {
            if pos(q, j) == last {
                with_pos(q, j, p)
            } else {
                *q
            }
        }
    }
}

