pub fn enqueue(q: &Queue, k: Kind, time: u64, replace: bool) -> Queue {
    match slot(q, k) {
        None => {
            let n = with_slot(q, k, Some(time));
            with_pos(&n, k, pending_count(q))
        }
        Some(existing) => {
            let v = if replace {
                time
            } else if existing < time {
                existing
            } else {
                time
            };
            with_slot(q, k, Some(v))
        }
    }
}

